mapper.select:
SELECT  FROM admin_api_keys
WHERE admin_user_id = #{adminUserId}
ORDER BY id DESC

mapper.insert:
INSERT INTO admin_api_keys (
    admin_user_id, name, key_prefix, key_hash, scopes, status, expires_at, created_by
) VALUES (
    #{adminUserId}, #{name}, #{keyPrefix}, #{keyHash}, #{scopes}, #{status},
    #{expiresAt,jdbcType=TIMESTAMP}, #{createdBy,jdbcType=BIGINT}
)

mapper.update:
UPDATE admin_api_keys
name = #{name}, scopes = #{scopes},
WHERE id = #{id}

UPDATE admin_api_keys
SET status = 'revoked',
    revoked_at = #{revokedAt},
    revoked_by = #{revokedBy,jdbcType=BIGINT},
    revoke_reason = #{revokeReason,jdbcType=VARCHAR}
WHERE id = #{id}
